esp_err_t management_pages_send_setup(httpd_req_t *request, const char *csrf)
{
    char page[1800];
    snprintf(page, sizeof(page), management_setup_page_template, csrf);
    return management_send_html(request, page);
}

esp_err_t management_pages_send_login(httpd_req_t *request)
{
    return management_send_html(request, management_login_page);
}

esp_err_t management_pages_send_login_throttled(httpd_req_t *request, int retry_after)
{
    char retry_after_header[12];
    char page[1400];
    snprintf(retry_after_header, sizeof(retry_after_header), "%d", retry_after);
    httpd_resp_set_hdr(request, "Retry-After", retry_after_header);
    snprintf(page, sizeof(page),
             "<!doctype html><meta name=viewport content='width=device-width,initial-scale=1'>"
             "<title>ESP32-NUT sign in paused</title><style>body{font:17px -apple-system,BlinkMacSystemFont,sans-serif;margin:2rem;max-width:32rem;color:#17212b}</style>"
             "<h1>ESP32-NUT sign in</h1><p>Too many failed attempts. Try again in <strong id=remaining>%d</strong> seconds.</p>"
             "<p>This page will reload automatically when sign-in is available.</p>"
             "<script>let remaining=%d;const output=document.getElementById('remaining');const timer=setInterval(()=>{remaining--;output.textContent=Math.max(remaining,0);if(remaining<=0){clearInterval(timer);location='/' }},1000)</script>",
             retry_after, retry_after);
    return management_send_html_status(request, "429 Too Many Requests", page);
}

#if defined(__GNUC__)
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wformat-truncation"
#endif

static esp_err_t management_pages_send_admin_template(httpd_req_t *request,
                                                       const char *page_template,
                                                       const char *csrf)
{
    char chunk[MANAGEMENT_PAGES_HTML_CHUNK_SIZE];
    size_t used = 0;
    esp_err_t result = management_start_html_chunks(request, "200 OK");
    if (result != ESP_OK)
    {
        return result;
    }

    for (const char *cursor = page_template; *cursor != '\0'; cursor++)
    {
        if (*cursor == '%' && cursor[1] == 's')
        {
            if (used > 0U &&
                management_send_html_chunk(request, chunk, used) != ESP_OK)
            {
                return ESP_FAIL;
            }
            used = 0;
            if (management_send_html_chunk(request, csrf, strlen(csrf)) != ESP_OK)
            {
                return ESP_FAIL;
            }
            cursor++;
            continue;
        }
        if (*cursor == '%' && cursor[1] == '%')
        {
            cursor++;
        }
        chunk[used++] = *cursor;
        if (used == sizeof(chunk))
        {
            if (management_send_html_chunk(request, chunk, used) != ESP_OK)
            {
                return ESP_FAIL;
            }
            used = 0;
        }
    }
    if (used > 0U && management_send_html_chunk(request, chunk, used) != ESP_OK)
    {
        return ESP_FAIL;
    }
    return management_end_html_chunks(request);
}

